'use strict';
/* FAILED MOVE BUY — FINAL WF, research only. Two pre-locked candidates from prior DEV/HOLD optimizer.
Q15: BIG1.5 IB.60 REC.30, bullish reclaim above impulse open, ATR ratio .75..2, block UTC 6/7/8, RR1.5.
W13: BIG1.3 IB.60 REC.30, CP>=.75, ATR ratio 1..2, block UTC 0..5, RR1.5.
Both: BUY only, SL=1 ATR, max hold 12 M5, next-bar open, causal. Reports full, 6 blocks, monthly, cost.
*/
const fs=require('fs'),z=JSON.parse(fs.readFileSync('data/xauusd-m5-dukascopy.json','utf8')),q=Array.isArray(z)?z:(z.candles||z.data||[]),M=q.map(x=>({t:+new Date(x.t||x.time||x.timestamp),o:+(x.o??x.open),h:+(x.h??x.high),l:+(x.l??x.low),c:+(x.c??x.close)})).filter(x=>Number.isFinite(x.t+x.o+x.h+x.l+x.c)).sort((a,b)=>a.t-b.t),N=M.length;
function atr(n=14){let a=Array(N).fill(null),tr=M.map((b,i)=>i?Math.max(b.h-b.l,Math.abs(b.h-M[i-1].c),Math.abs(b.l-M[i-1].c)):b.h-b.l),s=0;for(let i=0;i<N;i++){if(i<n){s+=tr[i];if(i===n-1)a[i]=s/n}else a[i]=(a[i-1]*(n-1)+tr[i])/n}return a}const A=atr(),AA=Array(N).fill(null);for(let i=60;i<N;i++){let s=0;for(let k=i-50;k<i;k++)s+=A[k]||0;AA[i]=s/50}
const P=[{name:'Q15',big:1.5,ib:.6,rec:.3,cp:.65,amin:.75,amax:2,block:new Set([6,7,8]),rr:1.5},{name:'W13',big:1.3,ib:.6,rec:.3,cp:.75,amin:1,amax:2,block:new Set([0,1,2,3,4,5]),rr:1.5}];
function run(p,lo=60,hi=N-2){let a=[],o=null;for(let i=lo;i<=hi;i++){if(o){let b=M[i],px=null;if(b.l<=o.sl)px=o.sl;else if(b.h>=o.tp)px=o.tp;if(px==null&&i-o.ei>=12)px=b.c;if(px!=null){a.push({...o,xi:i,xt:b.t,px,r:(px-o.en)/(o.en-o.sl),usd:px-o.en});o=null}continue}if(!A[i]||!AA[i])continue;let x=M[i-1],b=M[i],rg=x.h-x.l,br=b.h-b.l;if(rg<=0||br<=0||x.c>=x.o)continue;if(rg/A[i]<p.big||Math.abs(x.c-x.o)/rg<p.ib)continue;if(!(b.c>x.o&&b.h>x.h-p.rec*A[i]&&b.c>b.o&&(b.c-b.l)/br>=p.cp))continue;let ar=A[i]/AA[i];if(ar<p.amin||ar>p.amax||p.block.has(new Date(b.t).getUTCHours()))continue;let en=M[i+1].o,r=A[i];o={en,sl:en-r,tp:en+p.rr*r,ei:i+1,et:M[i+1].t}}return a}
function st(a){let gp=0,gl=0,w=0,e=0,pk=0,dd=0,ls=0,ml=0;for(let x of a){e+=x.r;if(x.r>0){gp+=x.r;w++;ls=0}else{gl+=-x.r;ls++;ml=Math.max(ml,ls)}pk=Math.max(pk,e);dd=Math.max(dd,pk-e)}return{n:a.length,wr:a.length?100*w/a.length:0,pf:gl?gp/gl:99,net:e,dd,ls:ml}}
const f=s=>`T${s.n} WR${s.wr.toFixed(1)} PF${s.pf.toFixed(2)} N${s.net>=0?'+':''}${s.net.toFixed(2)}R DD${s.dd.toFixed(2)} LS${s.ls}`;
console.log('FAILED MOVE BUY — FINAL WALK-FORWARD VALIDATION');console.log(`M5=${N} ${new Date(M[0].t).toISOString()} → ${new Date(M[N-1].t).toISOString()}`);
for(const p of P){const all=run(p);console.log(`\n===== ${p.name} =====`);console.log('FULL | '+f(st(all)));console.log('6 CONTIGUOUS BLOCKS');for(let k=0;k<6;k++){let lo=Math.max(60,Math.floor(N*k/6)),hi=Math.floor(N*(k+1)/6)-2;console.log(`B${k+1} ${new Date(M[lo].t).toISOString().slice(0,10)}→${new Date(M[hi].t).toISOString().slice(0,10)} | ${f(st(run(p,lo,hi)))}`)}console.log('MONTHLY');let mm={};for(let x of all){let key=new Date(x.xt).toISOString().slice(0,7);(mm[key]??=[]).push(x)}for(let [k,a] of Object.entries(mm))console.log(`${k} | ${f(st(a))}`);console.log('COST @ 0.01 LOT');for(let cost of[0,.2,.4,.6,1]){let gp=0,gl=0,w=0,e=0,pk=0,dd=0;for(let x of all){let v=x.usd-cost;e+=v;if(v>0){gp+=v;w++}else gl+=-v;pk=Math.max(pk,e);dd=Math.max(dd,pk-e)}console.log(`$${cost.toFixed(2)}/trade | T${all.length} WR${all.length?(100*w/all.length).toFixed(1):'0.0'} PF${(gl?gp/gl:99).toFixed(2)} NET$${e.toFixed(2)} DD$${dd.toFixed(2)}`)}}
console.log('\nDECISION: prefer stability across blocks/months and realistic $0.20 cost. Do not promote based on aggregate WR. If one survives, next test is 7-strategy portfolio + candidate collision/DD impact.');
